### 4. Your First Snap

```rust
use constraint_theory_core::{PythagoreanManifold, snap};

fn main() {
    // Create a Pythagorean manifold with density 200 (~1000 valid states)
    let manifold = PythagoreanManifold::new(200);

    // A point near the unit circle (noisy input)
